{"code": "export async function main(input: any) {
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  for (;;) {
    const page = await sdk.github.listCommits(cursor ? { cursor } : {});
    for (const c of page.commits) {
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
    }
    pages++;
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
    if (pages > 500) break;
  }
  return { pages, total: Object.values(counts).reduce((a, b) => a + b, 0), counts };
}"}
